import pathlib,json,re,hashlib,subprocess
D=pathlib.Path('/agent/workspace/owl-native-prep/real-probe-final');P=D.parent
assert (D/'summary.json').exists(),'Probe not finished'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
subprocess.run(['python3',str(D/'analyze.py')],stdout=(D/'analysis.log').open('w'),stderr=subprocess.STDOUT,check=True)
(D/'final-processes.txt').write_text(subprocess.check_output(['ps','-eo','pid,ppid,rss,comm,args'],text=True))
