(D/'source-binary-preservation.json').write_text(json.dumps({'unchanged':before==after,'hashes_after':after,'differences':[p for p in before if before[p]!=after[p]]},indent=2))
stdout=(D/'stdout.log').read_text();stderr=(D/'stderr.log').read_text();summary=json.loads((D/'summary.json').read_text());scores=json.loads((D/'independent-scores.json').read_text());preservation=json.loads((D/'prior-evidence-preservation.json').read_text())
