checks={name:(D/(name+'.error.txt')).exists() and text in (D/(name+'.error.txt')).read_text() for name,text in expected_errors.items()}
for name,expected in [('text-sanity','4'),('red-image-sanity','Red'),('unicode-positive','4'),('reload-text-sanity','4')]:checks[name]=(D/(name+'.output.txt')).exists() and (D/(name+'.output.txt')).read_text()==expected
for k in ['A','B']:checks['gui-'+k]=scores[k].get('production_codec_accepted',False) and scores[k].get('point_inside_search_bbox',False)
checks['close-acks']=all(k+'=true' in stdout for k in ['PRE_RELOAD_NATIVE_CLOSE_ACK','FINAL_NATIVE_CLOSE_ACK','SECOND_CLOSE_ACK'])
checks['normal-exit']=summary['exit_code']==0 and summary['termination']=='NORMAL_PROCESS_EXIT'
