rows=[]
for match in re.finditer(r'^PROBE (\d+) (SUCCESS|ERROR) ([^ ]+) elapsedMs=(\d+) (.*)$',stdout,re.M):
 timestamp,state,name,ms,message=match.groups();path=D/(name+('.output.txt' if state=='SUCCESS' else '.error.txt'));rows.append({'timestampMs':int(timestamp),'outcome':state,'name':name,'elapsedMs':int(ms),'headline':message,'raw_file':path.name})
(D/'all-outcomes.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
receipt=re.search(r'CONFIG (.*)',stdout).group(1)
report=['# Final real Owl probe after load-permit + stack-batch repairs','', '**SYNTHETIC HOST TEST — NOT ANDROID / NOT PHONE QUALIFICATION.**','', '## Result', '', ('PASS: all requested probe assertions passed.' if all(checks.values()) else 'INCOMPLETE/FAIL: see exact failed assertions below.')+' One run, no retries, no output repair or cherry-picking. All raw returns and exceptions retained. No actions dispatched.', '',f'Evidence: `{D}/`. Sole model JVM exited: `{summary["termination"]}`, exit `{summary["exit_code"]}`, wall `{summary["elapsed_seconds"]:.3f}s`. Resource-exclusive preflight, inference and final process snapshots retained. No Gradle, production edits, native compiler, downloads or commits. Standalone harness Kotlin compilation finished before model launch.', '', '## Identity and actual defaults','',f'```\n{receipt}\n```','', 'Called `load(modelRoot)` without budget overrides; GUI requests reserve all 256 output tokens. CPU2; actual ctx2048/output256/imageEdge512. Unchanged 256×256 synthetic fixtures are below max edge512 and tokenize to64 image tokens, not256. Actual production OwlPromptBuilder and OwlOutputCodec sources compiled into harness; actual repaired runtime/planner classes pinned without replacements. JNI loaded from own pinned copy, confirmed by `/proc/self/maps`; dependencies and sources hashed before/after.', '', 'Repaired production source binary origin: `/agent/workspace/owl-native-prep/race-production-host`. SHA pins asserted before launch and copied into `pinned-host/`:','']
for p,h in pins['expected_and_verified'].items():report.append(f'- `{p}`: `{h}`')
report+=['','Existing real 4B decoder and mmproj freshly streamed/hash verified; no redownload:']
